package com.agicore.api; import com.agicore.dialogue.DialogueOrchestrator; import com.agicore.persistence.DatabasePersistence; import com.agicore.domain.Contracts.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/chat") public class ChatController { private final DialogueOrchestrator o; private final DatabasePersistence db; public ChatController(DialogueOrchestrator o,DatabasePersistence db){this.o=o;this.db=db;} @PostMapping public AggregatedTaskResult chat(@RequestBody ChatRequest r){var result=o.execute(r); db.recordChat(r,result); return result;} }
